from book import Chapter
c=Chapter('07')
c.src('R49135',0,start='想要彻底消除不平等',end='获得更大的优势的工具了。',replacements=[('在过去是不可能完成的任务','仅靠对人的道德劝说，远远不够'),('身强力壮的成年男性，显然在体力劳动中远远强于娇小柔弱的老年女性','身强力壮的成年人，在许多体力任务上会比体弱者更有优势'),('造农民的','造成农民的'),('其效能超过人类，且产量巨大到能够做到人手一个的时候，可以说人类在这项能力上的差距就被抹平了','其效能超过个体能力，而且普及到人人可以使用时，人们在完成这类任务上的差距就有了被大幅缩小的条件'),('农民之间的农耕能力就被抹除了','个人体力差异对农耕能力的限制就大幅降低了'),('消除了人们寻路的能力差距','降低了人们寻路能力差距的影响'),('将抹除人类驾驶能力的区别','有望减少个人驾驶能力不同造成的限制'),('人们在生理上的能力差别正在被一点点的消除','人们因生理差别而受到的限制，可以被一点点减轻'),('人们在智力上的差别也会被消除','获取知识、理解问题和参与判断的能力差距，也有了进一步缩小的可能'),('不能被有个人','不能被某个人'),('但是自从','\n\n但是自从'),('当然要做到这一点','\n\n当然要做到这一点')])
c.add('''这段推理中，最容易被忽略的是后半部分。同一台机器，可以成为许多人共同增加能力的工具，也可以成为少数人扩大支配范围的工具。机器本身更强，并不能代替“谁能使用它、怎样使用它、谁来决定”的问题。

例如，两个人都能使用导航，过去对陌生道路的熟悉程度就不再那么决定结果；但如果只有一方可以获得完整地图，另一方只能在有限提示下行动，能力差距就换了一种形式继续存在。由此，平等的物质条件，不仅包括工具已经被发明，还包括知识、基础设施和使用权怎样分布。''')
c.heading('智力劳动为什么也能发生机器革命')
c.src('R34519',0,replacements=[('高质量高速的','高质量、高速度地'),('而AI革命必将实现智力劳动组织形式的革命','而 AI 的发展，为智力劳动组织形式的改变提供了新的条件'),('任何智力劳动的成果','越来越多能够清楚表达和实现的智力劳动成果'),('随意大规模复制','在具备相应资源与使用条件时大规模复制'),('你觉得呢？','')])
c.add('''一位熟练工匠知道怎样制造某个零件，这种能力首先依附于他的训练、经验和身体。把其中能够重复的操作落实到工具和生产过程之后，别人就不必重新经历同样漫长的学习，才有可能得到相近的结果。

智力劳动也有类似的一面。一个专家形成的判断规则，如果只能保存在他的脑中，其他人就必须不断向他求助；如果其中可表达、可检验的部分能够成为共同使用的模型、算法与知识，更多人就能站在这个基础上继续思考。专家仍然可以作出新贡献，但已经形成的能力，不必永远与某个身份绑在一起。

这并不意味着任何经验都已经能够被完整提取，也不意味着模型的一次回答就等同于专业判断。它说明的是一种组织可能：一部分原来依赖少数个体的能力，可以成为能够传播、检验和改进的共同基础。''')
c.heading('平等不要求每个人变成同一个人')
c.src('R54886',6,replacements=[('而现在信息已经可以完全透明，人类也已经具备了相应的生产力和基本能力','信息技术和 AI 的发展，使我们能够进一步研究这种可能'),('在发明 AI 之后，人类已经具备了这样的能力','我们希望逐步形成这样的能力'),('将人类所有的信息逐步转化为公共知识','将适合共同使用的信息逐步转化为公共知识'),('AI 实际上拉平了人与人之间的能力差距','AI 可以帮助缩小人与人之间的能力差距'),('人和人之间在具体的逻辑推理、思考以及理性博弈上的差距，已经不再存在了','使人在逻辑推理、思考以及理性博弈方面，不再仅仅受限于个人原有的知识条件')])
c.src('R54910',9,replacements=[('而现在这个AI大进化的年代','在 AI 持续发展的条件下'),('磨平','缩小'),('具备同等的人类知识DNA','获得共同的人类知识基础'),('就像每一个生物细胞都拥有整个的DNA信息','可以用许多细胞共享遗传信息作一个类比'),('时机已经成熟了','已经有了可以开始实践的技术入口')])
c.add('''共同的知识基础，不会让每个人自动产生相同兴趣。有人更喜欢机械，有人更关心艺术；有人愿意长期钻研一个问题，有人擅长把不同领域的成果接起来。工具可以减少因出身、身体和教育条件造成的障碍，而这些不同方向的选择，恰恰可以增加共同系统的创造能力。

所以，能力平等的方向，并不是把不同的人压成同一个模板，而是尽量避免一个人因为缺少入口，就永远只能接受别人的判断。一个此前没有专业训练的人，能否在工具帮助下理解与自己有关的决定，能否提出别人遗漏的事实，能否学习并参与新的工作，是比“所有人的分数是否相同”更直接的问题。''')
c.heading('生产力增加以后，为什么还需要改变组织形式')
c.src('R34498',1,end='达到充足供应的能力。',replacements=[('1. ','略去漫长的中间过程来看，'),('物质的丰富，使得人类个体生存所需的基本物质需求和精神需求得到基本满足','物质生产能力的提高，使满足基本生活需要获得了越来越强的技术条件'),('在不远的未来','我所期待的方向是，在持续改进生产与分配的过程中'),('人类个体生存所需的所有物质需求和精神需求都可以','人类个体生存所需的物质与精神需要，能够逐步')])
c.src('R54910',8,start='而人类社会的个体所形成的社会网络',replacements=[('是一种更加静态的金字塔结构','常常采用相对静态的金字塔结构'),('并不会因此就能快速的由更年富力强决策能力更强的新生代取代','并不一定随之及时调整'),('必然会导致资源的低效分布和浪费(绝对的权力产生绝对的腐败，垄断阻碍创新等都是这个原因)','容易形成资源的低效分配和浪费，使已经获得的权力继续保护自身，而不随实际能力和需要改变')])
c.add('''这里出现的矛盾，是生产能力已经能够越来越广泛地复制和传播，而组织权力仍然可能依附于固定位置。新工具进入以后，如果组织方式完全不变，工具带来的收益也可能继续沿着原有权力关系分配。

因此，不能只问 AI 能创造多少财富，还要问它怎样改变每一个人参与生产和判断的条件。若普通人只能贡献数据、承担变化，却不能理解和影响使用这些数据的规则，技术进步就没有自动完成制度进步。''')
c.heading('工作减少以后，创造是否也会消失')
c.add('''一个常见的担心是：如果机器替代了许多工作，人还剩下什么？这个问题里往往混合了两种含义：一种是为了获得生活条件而不得不完成的劳动，另一种是出于兴趣、责任和创造欲而进行的活动。

减少前一种负担，可以为后一种活动释放时间。但这个结果需要组织条件支持。如果生活资源始终只通过旧岗位获得，那么岗位减少就会变成威胁；如果基本生活得到保障，工具又使人能够参与原本做不到的创造，同一项技术变化就可能带来新的自由。

一个人想做一部电影，未必是因为世界缺少一份雇佣劳动，而可能是因为他有故事要讲。工具降低拍摄、剪辑和制作的门槛，会使这种表达更容易发生。科学问题、社区改善、游戏、艺术与个人学习，也有同样的空间。我们没有理由只承认当前已经被某家公司设成职位的活动，才算有价值的创造。''')
c.src('R54307',0,start='而如今这个计算机信息时代',end='推动人类社会的进一步进化发展。',replacements=[('这种对应，其实就是碳基生物智能生态系统','碳基生物智能体系'),('创造的一种更高效的硅基计算机智能系统','创造了在许多任务上更有效率的计算机智能系统'),('将迸发出更强大的进化力量','有望形成更强的共同创造能力')])
c.add('''由此，问题已经从“人和机器谁替代谁”，进入“人和机器怎样组成更有能力的社会”。要让共同能力真正积累，首先需要一种可以被不同人理解、使用和继续构造的知识环境。这就把我们带到语言、公共知识与文明记忆。''')
c.save({'reasoning':'工具缩小生理差异→使用条件决定收益→智力成果可复制→共同基础保留差异→生产关系调整→劳动与创造→公共知识','examples':['农业机械','导航地图','工匠与机器','专家经验变成可检验工具','个人电影创作'],'objections':['强工具自动带来平等吗','平等是否抹去多样性','AI能回答即能负责吗','岗位减少是否等于创造终结'],'voice':'保留作者2024年工具平等论述与2026年智力劳动、知识DNA、生产关系论述','status':'初校；未来充足供应表述为方向，不当作已实现事实'})
